import{_ as r,C as i,o as s,c,a2 as n,j as t,a,E as o}from"./chunks/framework.Di-jvWLj.js";const w=JSON.parse('{"title":"Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1792441266000}'),l={name:"roadmap.md"},h={id:"m1-issue-triage-end-to-end",tabindex:"-1"},p={id:"m2-mail-digest",tabindex:"-1"},u={id:"m3-dependency-upgrade",tabindex:"-1"};function m(g,e,b,f,k,y){const d=i("Badge");return s(),c("div",null,[e[9]||(e[9]=n('<h1 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h1><p>chamberu is built milestone by milestone, each defined by one real agent that has to work end to end. Everything on this page except the shipped packages is <strong>planned</strong>: designed, not built. There are no dates.</p><h2 id="shipped" tabindex="-1">Shipped <a class="header-anchor" href="#shipped" aria-label="Permalink to &quot;Shipped&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Contents</th></tr></thead><tbody><tr><td><code>@chamberu/core</code></td><td><code>defineAgent()</code>, trigger definitions, <code>RunEngine</code> (dispatch, scheduling, checkpoints, budgets, approvals, cancel, drain, recovery), effect tools, agent state, the <code>IStore</code> and <code>INotifier</code> contracts, <code>MemoryStore</code></td></tr><tr><td><code>@chamberu/test-kit</code></td><td><code>describeStoreContract</code>, <code>ControllableClock</code></td></tr><tr><td><code>@chamberu/scheduler</code></td><td><code>createScheduler()</code> (one locked hubwire component per <code>cron()</code> trigger, overlap policies, timezones), <code>runJob()</code> for one-shot jobs</td></tr><tr><td><code>@chamberu/store-typeorm</code></td><td><code>TypeormStore</code> on Postgres, <code>migrateStore</code>, <code>purgeExpired</code>. See <a href="/stores/typeorm">TypeORM store</a></td></tr><tr><td><code>@chamberu/http</code></td><td>REST control API, server-sent events, webhook intake, <code>/healthz</code>, <code>/readyz</code>, <code>/metrics</code>, the MCP endpoint, static-token, authup and OIDC authentication, graceful shutdown. See <a href="/guide/http">HTTP API &amp; MCP</a></td></tr></tbody></table><h2 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h2>',5)),t("h3",h,[e[0]||(e[0]=a("M1: issue triage end to end ",-1)),o(d,{type:"warning",text:"Planned"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#m1-issue-triage-end-to-end","aria-label":'Permalink to "M1: issue triage end to end <Badge type="warning" text="Planned" />"'},"​",-1))]),e[10]||(e[10]=t("p",null,"On every new issue in the owner's repositories, a triage agent labels it, checks for duplicates, tries to reproduce the bug against the latest release in a sandbox and posts a first reply asking for missing details. A periodic sweep catches issues missed while the agent was down.",-1)),e[11]||(e[11]=t("p",null,"M1 is done only when everything it needs ships: the TypeORM store, the scheduler, the HTTP and MCP API with authentication, the GitHub connector, local and Kubernetes sandboxes with coding tools, the OpenClaw and GitHub notifiers, the UI, the CLI, the base image, the Helm chart, the template repository, and the triage agent itself, deployed with Flux.",-1)),t("h3",p,[e[3]||(e[3]=a("M2: mail digest ",-1)),o(d,{type:"warning",text:"Planned"}),e[4]||(e[4]=a()),e[5]||(e[5]=t("a",{class:"header-anchor",href:"#m2-mail-digest","aria-label":'Permalink to "M2: mail digest <Badge type="warning" text="Planned" />"'},"​",-1))]),e[12]||(e[12]=t("p",null,[a("Every morning, and on request through OpenClaw, the owner gets a short digest: what matters today, what still needs action, what is waiting on others. Open loops are tracked in typed state collections across days. M2 adds a mail (IMAP) connector and "),t("strong",null,"threaded runs"),a(": a new run continues the conversation of an earlier one.")],-1)),t("h3",u,[e[6]||(e[6]=a("M3: dependency upgrade ",-1)),o(d,{type:"warning",text:"Planned"}),e[7]||(e[7]=a()),e[8]||(e[8]=t("a",{class:"header-anchor",href:"#m3-dependency-upgrade","aria-label":'Permalink to "M3: dependency upgrade <Badge type="warning" text="Planned" />"'},"​",-1))]),e[13]||(e[13]=n('<p>When Renovate opens a pull request, an agent reads the changelog of the bumped package, fixes breaking changes in a sandbox, runs the tests and pushes commits. It pings the owner only when it is stuck. M3 adds long coding runs, a Claude Code coding backend and stuck detection.</p><h2 id="planned-packages" tabindex="-1">Planned packages <a class="header-anchor" href="#planned-packages" aria-label="Permalink to &quot;Planned packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Status</th><th>Purpose</th></tr></thead><tbody><tr><td><code>@chamberu/github</code></td><td>Planned (M1)</td><td>GitHub App auth, webhook signature checks, <code>github.webhook()</code> triggers deduplicated by delivery id, issue and comment tools with marker reconciliation. See <a href="/deployment/github-app">GitHub App</a></td></tr><tr><td><code>@chamberu/sandbox-local</code>, <code>@chamberu/sandbox-k8s</code></td><td>Planned (M1)</td><td>Disposable workspaces: a temp directory for development, a locked-down pod per workspace in production</td></tr><tr><td><code>@chamberu/coding</code></td><td>Planned (M1)</td><td>Coding tools (read, edit, grep, bash, git diff) over a workspace</td></tr><tr><td><code>@chamberu/coding-claude-code</code></td><td>Planned (M3)</td><td>A coding backend that runs Claude Code inside the sandbox</td></tr><tr><td><code>@chamberu/notify-openclaw</code></td><td>Planned (M1)</td><td>Notifications into OpenClaw chats. See <a href="/deployment/openclaw">OpenClaw</a></td></tr><tr><td><code>@chamberu/notify-github</code></td><td>Planned (M1)</td><td>Notifications as issue or pull request comments</td></tr><tr><td><code>@chamberu/ui</code></td><td>Planned (M1)</td><td>Vue 3 dashboard: runs with live steps, approvals inbox, agent state, schedules</td></tr><tr><td><code>chamberu</code> (CLI and deploy kit)</td><td>Planned (M1)</td><td>Umbrella package with <code>createApp()</code> and the <code>dev</code>, <code>build</code>, <code>start</code>, <code>run-job</code> and <code>migrate</code> commands, plus a base image, a Helm chart and a template repository. See <a href="/deployment/">Deployment</a></td></tr><tr><td><code>@chamberu/mail</code></td><td>Planned (M2)</td><td>IMAP connector and tools</td></tr></tbody></table><p>Two changes happened upstream first: a lock hook, timezone support and the scheduled time per tick shipped in <a href="https://github.com/tada5hi/hubwire" target="_blank" rel="noreferrer">hubwire</a> 0.2.2 (for the scheduler), and a fetch-native token verification in <a href="https://github.com/authup/authup" target="_blank" rel="noreferrer">authup</a> 1.0.0-beta.70 (for the HTTP API).</p><h2 id="stability" tabindex="-1">Stability <a class="header-anchor" href="#stability" aria-label="Permalink to &quot;Stability&quot;">​</a></h2><p>chamberu is pre-1.0 and owner-first. Until M3, minor versions may break the API and the store schema.</p>',6))])}const x=r(l,[["render",m]]);export{w as __pageData,x as default};
